with scored as (select id, method, max(amount) over w_part as running_max_amount, count(amount) over w_part as running_count_amount, sum(amount) over w_part as running_sum_amount, min(amount) over w_part as running_min_amount from payments window w_part as (partition by method, order_id order by paid_at, id rows between unbounded preceding and current row)) select id, method, running_count_amount, running_min_amount, case when method rlike '^(cash|card)$' then 'OTHER_ZONE' when method rlike '^(paypal|bank_transfer)$' then 'CORE' else 'PRIORITY' end as method_zone from scored
